import merge from "deepmerge";
import { combineMergeArray } from "../../../utils/combineMergeArray";

export default function setSize(size, config) {
	if (!size) return;
	const { enableArcLinkLabels, legends, startAngle, endAngle } = config;
	const partialLimited = endAngle === 90 && Math.abs(startAngle) === endAngle;
	this.hasLegends = !this.sunburst && (legends === undefined || legends.length);
	this.rightLegend = legends?.[0]?.anchor && legends[0].anchor === "right";
	const { hasLegends, rightLegend } = this;
	let width;
	let height;
	let _margin;
	if (size === "small") {
		if (rightLegend) {
			if (enableArcLinkLabels) {
				_margin = { top: 20, bottom: 20, left: -10, right: 100 };
				width = 362;
				height = 208;
			} else {
				_margin = { top: 20, bottom: 20, left: -50, right: 80 };
				width = 365;
				height = 208;
			}
		} else if (hasLegends) {
			if (enableArcLinkLabels) {
				_margin = { top: 20, bottom: 80, left: 50, right: 50 };
				width = 286;
				height = 246;
			} else {
				_margin = { top: 20, bottom: 80, left: 0, right: 0 };
				width = 222;
				height = 268;
			}
		} else {
			if (enableArcLinkLabels) {
				_margin = { top: 20, bottom: 0, left: 50, right: 50 };
				width = 268;
				height = 242;
			} else {
				_margin = { top: 20, bottom: 20, left: 20, right: 20 };
				width = 208;
				height = 208;
			}
		}
	} else if (size === "medium") {
		if (rightLegend) {
			if (enableArcLinkLabels) {
				_margin = { top: 20, bottom: 20, left: -10, right: 100 };
				width = 440;
				height = 286;
			} else {
				_margin = { top: 20, bottom: 20, left: -50, right: 100 };
				width = 440;
				height = 286;
			}
		} else if (hasLegends) {
			if (enableArcLinkLabels) {
				_margin = { top: 20, bottom: 80, left: 50, right: 50 };
				width = 346;
				height = 346;
			} else {
				if (partialLimited) {
					_margin = { top: 20, bottom: 80, left: 20, right: 20 };
					width = 285;
					height = 220;
				} else {
					_margin = { top: 20, bottom: 80, left: 20, right: 20 };
					width = 300;
					height = 346;
				}
			}
		} else {
			if (enableArcLinkLabels) {
				_margin = { top: 20, bottom: 0, left: 50, right: 50 };
				width = 346;
				height = 320;
			} else {
				if (this.sunburst) {
					_margin = { top: 20, bottom: 20, left: 20, right: 20 };
					width = 304;
					height = 304;
				} else {
					_margin = { top: 20, bottom: 20, left: 20, right: 20 };
					width = 286;
					height = 286;
				}
			}
		}
	} else if (size === "large") {
		if (rightLegend) {
			if (enableArcLinkLabels) {
				_margin = { top: 20, bottom: 20, left: -10, right: 100 };
				width = 570;
				height = 415;
			} else {
				_margin = { top: 20, bottom: 20, left: -50, right: 100 };
				width = 568;
				height = 415;
			}
		} else if (hasLegends) {
			if (enableArcLinkLabels) {
				_margin = { top: 20, bottom: 80, left: 50, right: 50 };
				width = 475;
				height = 475;
			} else {
				_margin = { top: 20, bottom: 80, left: 20, right: 20 };
				width = 428;
				height = 475;
			}
		} else {
			if (enableArcLinkLabels) {
				_margin = { top: 20, bottom: 0, left: 50, right: 50 };
				width = 475;
				height = 450;
			} else {
				_margin = { top: 20, bottom: 20, left: 20, right: 20 };
				width = 415;
				height = 415;
			}
		}
	}

	config.margin = config.margin
		? merge.all([_margin, config.margin], {
				arrayMerge: combineMergeArray,
		  })
		: _margin;

	return {
		width: `${width}px`,
		height: `${height}px`,
	};
}
