import React from "react";

export function radialLabel(el, children) {
	let radialLabels;
	const childrenArr = Array.from(children);
	const firstChild = childrenArr[0] as HTMLElement;
	const secondChild = childrenArr[1] as HTMLElement;
	if (
		firstChild.tagName === "path" &&
		secondChild.tagName === "g" &&
		secondChild.children
	) {
		radialLabels = true;
		[...children].forEach((c, i) => {
			const isEven = i % 2 === 0;
			if (isEven) {
				c.classList.add("--donut-radialLabel--path");
			} else {
				c.classList.add("--donut-radialLabel");
				c.firstElementChild.classList.add("--donut-radialLabel-text");
			}
		});
	}
	if (radialLabels) {
		el.classList.add("hbr-donut_radialLabels");
	}
}

export function radialLabelLayer(props) {
	const { partialLimited, sunburst, radialLabel } = this;
	const { text, format } = radialLabel;
	const { centerX, centerY, innerRadius } = props;
	let dataWithArc;
	let nodes;
	let total = 0;
	if (sunburst) {
		nodes = props.nodes;
		nodes.forEach((datum) => (total += datum.depth === 1 ? datum.value : 0));
	} else {
		dataWithArc = props.dataWithArc;
		dataWithArc.forEach((datum) => (total += datum.value));
	}
	const large = this.size && this.size === "large";
	const distanceTop = partialLimited
		? centerY - innerRadius + innerRadius / 2
		: centerY - 12;
	const distanceBottom = partialLimited
		? centerY - innerRadius + innerRadius / 2 + innerRadius / 4
		: centerY + 12;

	return React.createElement(
		"g",
		{
			className: "--layer-radialLabel",
		},
		React.createElement(
			"text",
			{
				x: centerX,
				y: distanceTop,
				textAnchor: "middle",
				className: "--layer-radialLabel-total",
				dominantBaseline: "central",
				fontSize:
					this === "partialLimited"
						? large
							? "var(--hbr-font-size-2xl)"
							: "var(--hbr-font-size-sm)"
						: "var(--hbr-font-size-xl)",
				fontWeight: "var(--hbr-font-weight-normal)",
				letterSpacing: "var(--hbr-font-letter-spacing-loose)",
				fill: "var(--hbr-color-neutral-text-weak)",
			},
			format ? format(total) : total,
		),
		React.createElement(
			"text",
			{
				x: centerX,
				y: distanceBottom,
				textAnchor: "middle",
				className: "--layer-radialLabel-desc",
				dominantBaseline: "central",
				fontSize:
					this === "partialLimited"
						? large
							? "var(--hbr-font-size-sm)"
							: "var(--hbr-font-size-2xs)"
						: "var(--hbr-font-size-2xs)",
				fontWeight: "var(--hbr-font-weight-light)",
				letterSpacing: "var(--hbr-font-letter-spacing-loose)",
				fill: "var(--hbr-color-neutral-text-weak)",
			},
			text,
		),
	);
}
